//! Renders the component specs of `dodai-core` ([`dodai_core::component_spec`]) into plain Rust
//! for each toolkit: a `<Name>Style` struct of native colours and a `<Name>Style::of(theme, ..)`
//! that resolves the tokens and converts them. Drawing stays hand-written and reads the style.
//!
//! A [`Target`] pays off only where the drawing code takes native colours. egui's painter takes
//! core colours, so it is not a target.

use dodai_core::component_spec::{ComponentSpec, FieldKind};
use std::fmt::Write as _;

/// One toolkit crate that gets a generated file.
pub struct Target {
    /// Crate directory name, for messages.
    pub name: &'static str,
    /// Output path from the repository root.
    pub path: &'static str,
    /// The toolkit's colour type.
    pub color_ty: &'static str,
    /// Function from a core colour to `color_ty`.
    pub convert: &'static str,
    /// Value for an absent colour; `None` keeps an `Option` of the colour type.
    pub transparent: Option<&'static str>,
}

/// The toolkits that take native colours.
pub const TARGETS: &[Target] = &[Target {
    name: "dodai-xilem",
    path: "crates/dodai-xilem/src/generated.rs",
    color_ty: "xilem::Color",
    convert: "crate::color",
    transparent: Some("xilem::Color::TRANSPARENT"),
}];

/// `tag` -> `Tag`, `data_table` -> `DataTable`.
pub fn pascal(s: &str) -> String {
    s.split('_')
        .map(|w| {
            let mut c = w.chars();
            c.next()
                .map(|f| f.to_uppercase().chain(c).collect::<String>())
                .unwrap_or_default()
        })
        .collect()
}

/// The core types the argument lists mention (everything starting with a capital).
fn imports(specs: &[ComponentSpec]) -> Vec<&'static str> {
    let mut v: Vec<&str> = specs
        .iter()
        .flat_map(|s| s.args.iter().map(|a| a.ty))
        .filter(|t| t.starts_with(|c: char| c.is_uppercase()))
        .collect();
    v.push("Theme");
    v.sort_unstable();
    v.dedup();
    v
}

/// The unformatted source of one target.
pub fn render(specs: &[ComponentSpec], t: &Target) -> String {
    let mut o = String::from(
        "// @generated by `cargo run -p dodai-gen` from the component specs of dodai-core. Do not edit.\n\n",
    );
    let _ = writeln!(o, "use dodai_core::{{{}}};", imports(specs).join(", "));
    for s in specs {
        let ty = pascal(s.name);
        let field_ty = |k: FieldKind| match (k, t.transparent) {
            (FieldKind::OptColor, None) => format!("Option<{}>", t.color_ty),
            _ => t.color_ty.to_string(),
        };
        let _ = writeln!(o, "\n/// {}", s.doc);
        let _ = writeln!(
            o,
            "#[derive(Debug, Clone, Copy, PartialEq)]\npub struct {ty}Style {{"
        );
        for f in s.fields {
            let _ = writeln!(
                o,
                "    /// {}.\n    pub {}: {},",
                f.name,
                f.name,
                field_ty(f.kind)
            );
        }
        let params: String = s
            .args
            .iter()
            .map(|a| format!(", {}: {}", a.name, a.ty))
            .collect();
        let call = s.args.iter().map(|a| a.name).collect::<Vec<_>>().join(", ");
        let _ = writeln!(o, "}}\n\nimpl {ty}Style {{");
        let _ = writeln!(o, "    /// The style of `theme` for these arguments.");
        let _ = writeln!(o, "    pub fn of(theme: &Theme{params}) -> Self {{");
        let _ = writeln!(
            o,
            "        let tok = theme.{}({call});\n        Self {{",
            s.resolver
        );
        for f in s.fields {
            let conv = t.convert;
            let _ = match (f.kind, t.transparent) {
                (FieldKind::OptColor, Some(none)) => {
                    writeln!(
                        o,
                        "            {0}: tok.{0}.map_or({none}, {conv}),",
                        f.name
                    )
                }
                (FieldKind::OptColor, None) => {
                    writeln!(o, "            {0}: tok.{0}.map({conv}),", f.name)
                }
                (FieldKind::Color, _) => writeln!(o, "            {0}: {conv}(tok.{0}),", f.name),
            };
        }
        o.push_str("        }\n    }\n}\n");
    }
    o
}

/// `source` through `rustfmt` (edition 2021), so the file matches `cargo fmt`.
pub fn format(source: &str) -> std::io::Result<String> {
    use std::io::Write;
    use std::process::{Command, Stdio};
    let mut child = Command::new("rustfmt")
        .args(["--edition", "2021", "--emit", "stdout"])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()?;
    child
        .stdin
        .take()
        .expect("piped")
        .write_all(source.as_bytes())?;
    let out = child.wait_with_output()?;
    if !out.status.success() {
        return Err(std::io::Error::other("rustfmt failed"));
    }
    Ok(String::from_utf8_lossy(&out.stdout).into_owned())
}

#[cfg(test)]
mod tests {
    use super::*;
    use dodai_core::component_spec::{Arg, Field};

    const SPEC: ComponentSpec = ComponentSpec {
        name: "data_row",
        doc: "d",
        resolver: "row",
        tokens: "RowTokens",
        args: &[
            Arg {
                name: "solid",
                ty: "bool",
            },
            Arg {
                name: "tone",
                ty: "Tone",
            },
        ],
        fields: &[
            Field {
                name: "border",
                kind: FieldKind::OptColor,
            },
            Field {
                name: "text",
                kind: FieldKind::Color,
            },
        ],
    };

    fn target(transparent: Option<&'static str>) -> Target {
        Target {
            name: "t",
            path: "p",
            color_ty: "C",
            convert: "conv",
            transparent,
        }
    }

    #[test]
    fn pascal_case() {
        assert_eq!(
            (pascal("tag").as_str(), pascal("data_table").as_str()),
            ("Tag", "DataTable")
        );
    }

    #[test]
    fn absent_colours_become_transparent_or_stay_optional() {
        let a = render(&[SPEC], &target(Some("C::NONE")));
        assert!(a.contains("pub struct DataRowStyle"));
        assert!(a.contains("border: tok.border.map_or(C::NONE, conv),"));
        assert!(a.contains("pub fn of(theme: &Theme, solid: bool, tone: Tone)"));
        assert!(a.contains("theme.row(solid, tone)"));
        assert!(a.contains("use dodai_core::{Theme, Tone};"));
        let b = render(&[SPEC], &target(None));
        assert!(b.contains("pub border: Option<C>,"));
        assert!(b.contains("border: tok.border.map(conv),"));
    }

    #[test]
    fn rustfmt_output_is_stable() {
        let once = format(&render(&[SPEC], &target(None))).unwrap();
        assert_eq!(format(&once).unwrap(), once);
    }
}
